fn numpy_where(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // All three vectors must have the same length.
    let n = condition.len();
    assert_eq!(x.len(), n, "x and condition must have the same length");
    assert_eq!(y.len(), n, "y and condition must have the same length");

    // Zip the three input vectors together and build the result.
    condition
        .into_iter()
        .zip(x.into_iter())
        .zip(y.into_iter())
        .map(|((cond, xv), yv)| if cond { xv } else { yv })
        .collect()
}

